"use client"

import { useState } from "react"
import Sidebar from "@/components/sidebar"
import MainContent from "@/components/main-content"


// This matches the type expected by main-content.tsx
export interface SharedState {
  selectedTemplate: string
  analysisDepth: string
  textTemplate: string
}

export default function Home() {
  // Initialize the state that controls the dashboard
  const [sharedState, setSharedState] = useState<SharedState>({
    selectedTemplate: "The Game Flow",
    analysisDepth: "Analyst", // Defaults to the Creator/Analyst mode
    textTemplate: "Standard",
  })

  return (
    // The main wrapper: full screen, flex row, dark background
    <div className="flex h-screen w-full overflow-hidden" style={{ backgroundColor: "#0d1117" }}>
      {/* Pass the state to the Sidebar so it can update it */}
      <Sidebar sharedState={sharedState} setSharedState={setSharedState} />
      
      {/* Pass the state to the MainContent so it knows what to display */}
      <MainContent sharedState={sharedState} />
    </div>
  )
}